// Format student answers as a clean Telegram message for the admin
const data = $input.first().json.body || $input.first().json;

const name = data.name || 'غير معروف';
const goal = data.goal || '—';
const why = data.why || '—';
const future = data.future || '—';
const risk = data.risk || '—';
const scale = data.commitment_scale || '?';
const scaleReason = data.scale_reason || '—';
const obstacle = data.obstacle || '—';
const commitment = data.commitment || '—';
const habit = data.habit || '—';
const message = data.message || '—';
const telegramUsername = data.telegram_username || 'N/A';
const telegramId = data.telegram_id || 'N/A';
const source = data.source || 'unknown';
const timestamp = data.timestamp || new Date().toISOString();

const text = `👑 *إجابة جديدة — Empire Goal Form*
━━━━━━━━━━━━━━━━━━

👤 *الاسم:* ${name}
🔗 *Telegram:* ${telegramUsername ? '@' + telegramUsername : 'N/A'}
📍 *المصدر:* ${source === 'telegram_webapp' ? 'Telegram WebApp' : 'رابط مباشر'}
🕐 *الوقت:* ${timestamp}

━━━━━━━━━━━━━━━━━━

🎯 *هدفي الأساسي:*
${goal}

💡 *ليه مهم:*
${why}

✨ *لو حققت هدفي:*
${future}

⚠️ *لو ما التزمتش:*
${risk}

📊 *مستوى الجدية:* ${scale}/10
💬 *السبب:* ${scaleReason}

🚧 *أكبر تحدي:*
${obstacle}

✊ *التزامي:*
${commitment}

☀️ *عادتي اليومية:*
${habit}

💌 *رسالة لنفسي:*
${message}

━━━━━━━━━━━━━━━━━━
🏛 Empire English Community`;

return [{ json: { text, name, telegramUsername } }];
